import{_ as l,o as e,c as n,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"CDS Hammer (Day 1) - RGW: Bucket Index Scalability","description":"","frontmatter":{"title":"CDS Hammer (Day 1) - RGW: Bucket Index Scalability","date":"2014-10-29T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["Ceph","分布式存储","Bucket Index Scalability","RGW","多区域"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_1_-_RGW_-_Bucket_Index_Scalability.md","filePath":"posts/2014/CDS_Hammer_Day_1_-_RGW_-_Bucket_Index_Scalability.md","lastUpdated":1780459816000}'),s={name:"posts/2014/CDS_Hammer_Day_1_-_RGW_-_Bucket_Index_Scalability.md"};function o(r,t,a,g,u,c){return e(),n("div",null,[...t[0]||(t[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph 分布式存储项目讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Guang、Patrick 等人</p><p><strong>会议内容</strong>：</p><p><strong>一、bucket 可扩展性</strong></p><ul><li><strong>背景</strong>： 探讨了 bucket 可扩展性，特别是 bucket 索引的扩展性。</li><li><strong>进展</strong>： 该功能进展顺利，已完成大部分工作，但与多区域、多区域功能的集成尚未完成。主要问题在于后台索引中存在一些日志，需要确保多区域环境下的正常工作。</li><li><strong>解决方案</strong>： 通过使用不同类型的标记或标记来识别不同 bucket 的位置，实现多区域下的 bucket 索引。</li><li><strong>下一步</strong>： 等待 Guang 回来后，进一步讨论该功能的细节。</li></ul><p><strong>二、list 命令</strong></p><ul><li><strong>讨论</strong>： 讨论了添加两个不同的 list 命令：传统的有序 list 命令和新的无序 list 命令。</li><li><strong>进展</strong>： 无序 list 命令尚未实现，但应该比较容易添加。</li><li><strong>问题</strong>： 位置标识符需要从键名对象改为元组，以支持无序 list 命令。</li></ul><p><strong>三、multi-object 上传的原子性</strong></p><ul><li><strong>讨论</strong>： 讨论了 multi-object 上传的原子性问题。</li><li><strong>结论</strong>： multi-object 上传需要所有条目都在同一个 bucket 中，因此不会影响原子性。</li></ul><p><strong>四、blind buckets</strong></p><ul><li><strong>讨论</strong>： 讨论了 blind buckets 的实现情况。</li><li><strong>结论</strong>： 目前没有实现 blind buckets，因为它会牺牲多区域、多区和对象版本化等功能。</li></ul><p><strong>五、object engine 分支</strong></p><ul><li><strong>讨论</strong>： 讨论了 object engine 分支与 bucket 可扩展性功能的冲突。</li><li><strong>结论</strong>： 由于两个功能没有涉及到相同的代码区域，因此不太可能存在冲突。</li></ul><p><strong>六、radi Gateway agent</strong></p><ul><li><strong>讨论</strong>： 讨论了 Guang 是否会继续工作在 radi Gateway agent 上。</li><li><strong>结论</strong>： 希望有新加入的成员能够帮助 Guang 工作。</li></ul><p><strong>七、bucket 分片</strong></p><ul><li><strong>讨论</strong>： 讨论了 bucket 分片的实现方式。</li><li><strong>结论</strong>： 可以通过以下步骤实现 bucket 分片： <ol><li>在 bucket 创建之前进行分片。</li><li>对于已经存在的 bucket，可以将其转换为新的分片 bucket。</li></ol></li></ul><p><strong>八、行动计划</strong></p><ul><li>等待 Guang 回来后，进一步讨论 bucket 可扩展性功能的细节。</li><li>实现无序 list 命令。</li><li>完成radi Gateway agent 的开发工作。</li><li>实现bucket 分片功能。</li></ul><p><strong>九、会议总结</strong></p><p>本次会议讨论了 Ceph 分布式存储项目的多个议题，包括 bucket 可扩展性、list 命令、multi-object 上传、blind buckets、object engine 分支、radi Gateway agent 和 bucket 分片等。会议明确了下一步的行动计划，并希望新加入的成员能够为项目贡献力量。</p>',23)])])}const b=l(s,[["render",o]]);export{p as __pageData,b as default};
